/* @lc app=leetcode id=3676 lang=kotlin */ class Solution { fun bowlSubarrays(nums: IntArray): Long = java.util.ArrayDeque<Int>().let { st -> nums.indices.sumOf { i -> generateSequence { st.peekFirst()?.takeIf { nums[it] < nums[i] } }.map { st.pollFirst() }.count { j -> i - j >= 2 }.also { st.addFirst(i) } } }.toLong() + java.util.ArrayDeque<Int>().let { st -> nums.indices.reversed().sumOf { i -> generateSequence { st.peekFirst()?.takeIf { nums[it] < nums[i] } }.map { st.pollFirst() }.count { j -> j - i >= 2 }.also { st.addFirst(i) } } }.toLong() }